```yaml
name: Discover new CLAUDE.md files

on:
  schedule:
    # Run every Sunday at 00:00 UTC
    - cron: '0 0 * * 0'

permissions:
  contents: read
  issues: write

jobs:
  discover:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Discover and create issues for new CLAUDE.md files
        uses: actions/github-script@v6
        with:
          script: |
            const query = 'filename:CLAUDE.md in:file language:Markdown';
            const per_page = 30; // limit to first page of results

            // Perform the search
            const { data: searchData } = await github.rest.search.code({
              q: query,
              per_page
            });

            // Load known repos from repos.txt if it exists
            const fs = require('fs');
            const knownRepos = new Set();
            if (fs.existsSync('repos.txt')) {
              const content = fs.readFileSync('repos.txt', 'utf8');
              content.split('\n').forEach(line => {
                const repo = line.trim();
                if (repo) knownRepos.add(repo);
              });
            }

            // Iterate over search results
            for (const item of searchData.items) {
              const repoFullName = item.repository.full_name;

              // Skip if already known
              if (knownRepos.has(repoFullName)) continue;

              // Check if an issue for this repo already exists
              const issueSearch = await github.rest.search.issuesAndPullRequests({
                q: `repo:${context.repo.owner}/${context.repo.repo} is:issue is:open ${repoFullName}`
              });

              if (issueSearch.data.total_count > 0) continue;

              // Create a new issue
              await github.rest.issues.create({
                owner: context.repo.owner,
                repo: context.repo.repo,
                title: `Add ${repoFullName} to awesome-claude-md`,
                body: `Found a new CLAUDE.md file in [${repoFullName}](${item.html_url}).\n\nLink to file: ${item.html_url}\n\nPlease review and consider adding it to the collection.`,
                labels: ['enhancement', 'automation']
              });
            }
